const revisedFinancialLabels={"balance": {"8": "Assets", "10": "Non-current assets", "12": "Property, plant and equipment", "13": "Right of use assets", "16": "Current Assets", "17": "Inventories", "18": "Trade receivables", "19": "Advances, deposits and pre- payments", "20": "Short term investment", "21": "Cash and cash equivalents", "24": "Total Assets", "26": "Equity and liabilities", "28": "Shareholders' equity", "29": "Share capital", "30": "Retained earnings", "34": "Non-current liabilities", "35": "Deferred tax liabilities", "36": "Long term loan-long term portion", "37": "Lease liabilities: non-current portion", "40": "Current liabilities", "41": "Long term loan-current portion", "42": "Lease liabilities: current portion", "43": "Trade and other liabilities", "44": "Income tax liabilities", "45": "Short term loan", "46": "Unclaimed dividend account", "47": "Total current liabilities", "49": "Total Equity and Liabilities", "51": "Net Asset Value Per Share", "14": "Total Non-current Assets", "22": "Total Current Assets", "32": "Total Shareholders' equity", "38": "Total Non-current liabilities"}, "cashflow": {"8": "Collection from customers and others", "9": "Payment for suppliers, employees and others ", "10": "Payment for WPPF", "11": "Income tax paid", "12": "Interest paid", "13": "Net cash inflow/(outflow) from operating activities", "15": "Cash flows from investing activities", "16": "Payment for the Acquisition of Property, Plant & Equipment", "17": "Payment for the Capital Work-In-Progress", "18": "(Increase)/ Decrease in Short Term Investment", "19": "Dividend income", "20": "Net cash inflow/(outflow) from investing activities", "22": "Cash flows from financing activities", "23": "Dividend paid", "24": "Receipt/(payment) of short term loan", "25": "Receipt/(payment) of long term loan ", "26": "Receipt/(payment) of lease liabilities- principal portion", "27": "Receipt/(payment) of lease liabilities interest portion", "28": "Receipt/(payment) of loan from different securities ltd", "29": "Receipt/(payment) of loan from intercompany", "30": "Net cash inflow/(outflow) from financing activities", "32": "Net increase/(decrease) in cash and cash equivalents", "33": "Cash and cash equivalents at the beginning of the period", "34": "Cash and cash equivalents at the year End", "36": "Net Operating Cash Flow Per Share (NOCFPS)"}};
function revisedKind(c){if(c.A1==='SBU Name'&&c.C1==='Segment')return 'income';if(c.A1==='SBU Name'&&c.C1==='General Ledger')return 'detail';if(c.A1==='SBU Name'&&c.C1==='Statement Category')return 'balance';if(c.B1==='SBU Name'&&c.D1==='Statement Category')return 'cashflow';return null;}
function convertRevised(raw){const c=raw.cells,kind=revisedKind(c);if(!kind)return null;const pair=['income','detail'].includes(kind),start=pair?3:2,nc=kind==='cashflow'?'B':'A',codeCol=kind==='cashflow'?'C':'B',lc=kind==='income'?'D':kind==='cashflow'?'F':'E',dateStart=kind==='income'?4:kind==='detail'?5:kind==='balance'?7:8,groups=new Map();for(let r=start;r<=1000;r++){if(!c[lc+r])continue;const name=clean(c[nc+r]),code=clean(c[codeCol+r]);if(!name)throw Error('Missing SBU name on row '+r);const key=keyOf(name);if(!groups.has(key))groups.set(key,{name,code,rows:[]});const g=groups.get(key);if(g.code!==code)throw Error('Conflicting SBU codes for '+name);g.rows.push(r);}const dates=[];let last;for(let j=dateStart;j<300;j++){if(typeof c[col(j)+'1']==='number')last=c[col(j)+'1'];if(pair&&!['Budget','Actual'].includes(c[col(j)+'2']))continue;if(!pair&&typeof c[col(j)+'1']!=='number')continue;if(!last||!parsePeriod(last))throw Error('Missing or invalid month header');dates.push({j,date:last,type:pair?c[col(j)+'2']:'Actual'});}if(!dates.length)throw Error('No dated data columns found');const periodKeys=new Set();for(const d of dates){const p=parsePeriod(d.date),key=p.year+'-'+p.month+'-'+d.type;if(periodKeys.has(key))throw Error('Duplicate reporting month and type');periodKeys.add(key);}
return [...groups.values()].map(g=>{const cells={},sourceCells={},rowGroups={};if(pair){cells.A1='Unit: '+g.name;cells.A3=kind==='income'?'Segment':'General Ledger';cells.B3=kind==='income'?'Particulars':'Sub-Ledger';if(kind==='detail')cells.C3='Particulars';}else{cells.B1=g.name;cells.B2=kind==='balance'?'Statement of Financial Position':'Statement of Cash Flows';cells.B5='Particulars';}const used=new Set();g.rows.forEach((r,i)=>{let target=i+5;if(!pair){const match=Object.entries(revisedFinancialLabels[kind]).find(([rr,l])=>keyOf(l)===keyOf(c[lc+r]));target=match?+match[0]:100+r;}if(used.has(target))throw Error('Duplicate statement line: '+c[lc+r]);used.add(target);if(kind==='income'){cells['A'+target]=c['C'+r];cells['B'+target]=c['D'+r];}else if(kind==='detail'){cells['A'+target]=c['C'+r];cells['B'+target]=c['D'+r];cells['C'+target]=c['E'+r];}else cells['B'+target]=c[lc+r];rowGroups[target]=pair?c['C'+r]:c[(kind==='balance'?'D':'D')+r];dates.forEach((d,idx)=>{const targetCol=col((pair?(kind==='income'?2:3):5)+idx),address=targetCol+target,original=col(d.j)+r;if(pair){cells[targetCol+'3']=d.date;cells[targetCol+'4']=d.type;}else cells[targetCol+'5']=d.date;if(c[original]!==undefined)cells[address]=typeof c[original]==='number'?c[original]:null;sourceCells[address]=original;});});return {kind,sbuName:g.name,book:{name:raw.name,sheet:raw.sheet,cells,sourceCells,rowGroups,sbuCode:g.code,layout:'sbu-header-v2'}};});}
delete views.notes;delete views.balance;delete views.equity;views.upload='Data Upload';let uploadSelection={sbu:'',segment:'all',name:'',code:''},uploadTarget=null;
addAttachedFinancials=async function(saved){if(saved.sourceRevision==='2026-10-15-agl-v2')return saved;const financial=await(await fetch('financial.json',{cache:'no-store'})).json(),next=structuredClone(saved),name=detectSbu(baseTemplate.income.cells),id=makeSbuId(name);next.sbus[id]={name,code:'AGL',books:{...structuredClone(baseTemplate),...financial}};next.financialAttachmentVersion=2;next.sourceRevision='2026-10-15-agl-v2';await persist(next);return next;};
function blankTemplatesView(){return panel('Blank Excel templates','Download a template, enter your SBU details and data, then upload the completed file.',table(['Template','Contents','Download'],[['IS','Income statement · monthly Budget / Actual'],['Break_Up','Expense break-up · ledger, sub-ledger and particulars'],['BS','Balance sheet · monthly balances'],['CFS','Cash-flow statement · monthly movements'],['SCE','Statement of changes in equity · opening, movements and closing']].map(([key,label])=>[key==='Break_Up'?'Break Up':key,label,`<a class="action" href="templates/${key}_Template.xlsx" download>Download Excel</a>`])))+`<p class="source">All financial input cells and SBU identifiers are blank. Fill SBU Name and SBU Code on every statement row; for SCE, enter the SBU name in A1. Keep the existing line items and headers. IS, Break Up, BS and CFS retain the source periods January 2024–September 2026; SCE retains January–September 2026 and the December 2025 opening balance. Enter 0 only for confirmed zero values. Keep unavailable values blank.</p>`;}
function uploadView(){if(!uploadSelection.sbu)uploadSelection.sbu=activeSbu;const selected=portfolio.sbus[uploadSelection.sbu];return panel('Upload data by SBU and statement segment','Select the destination before choosing one or more Excel files.',`<div class="plan-fields">${select('uploadSbu','Destination SBU',[...Object.entries(portfolio.sbus).map(([id,s])=>[id,s.name]),['auto','Detect SBUs from files'],['new','Add a new SBU']],uploadSelection.sbu)}${select('uploadSegment','Statement segment',[['all','Multiple segments / detect from files'],['income','Income statement'],['detail','Expense break-up'],['balance','Balance sheet'],['cashflow','Cash-flow statement'],['equity','Changes in equity'],['pricing','Net Sales Price'],['financial','Balance sheet, cash flow & equity']],uploadSelection.segment)}<div class="field"><label>Upload destination</label><p>${esc(selected?.name||'New SBU')} · ${esc(selected?.code||selected?.books.income?.sbuCode||'')}</p></div></div>${uploadSelection.sbu==='new'?`<div class="plan-fields"><div class="field"><label for="newSbuName">SBU name</label><input class="search" id="newSbuName" value="${esc(uploadSelection.name)}" placeholder="Full business-unit name"></div><div class="field"><label for="newSbuCode">SBU code</label><input class="search" id="newSbuCode" value="${esc(uploadSelection.code)}" placeholder="For example: AGL"></div></div>`:''}<p>Select multiple files together for the same SBU. The revised templates identify the SBU in each row. Their embedded names or codes must match the destination.</p><button class="action" id="chooseSegmentFiles">Choose Excel files</button><div class="upload-progress" id="uploadProgress"><div class="track"><div class="bar" id="uploadProgressBar"></div></div><div class="meta"><span id="uploadProgressLabel">Reading files…</span><span id="uploadProgressPct">0%</span></div></div><p class="source">Review the detected worksheets before import. Each imported statement segment replaces that segment’s full dataset; include all periods to retain. Other statement segments and SBUs remain unchanged.</p>`)+blankTemplatesView()+panel('Blank Net Sales Price templates','SBU identifiers and monthly values are blank. Product labels and source layouts are retained.',`<div class="actions">${['AGL','AIL','ACL'].map(code=>`<a class="action" href="templates/${code}_Net_Sales_Price_Template.xlsx" download>${code} pricing template</a>`).join('')}</div><p>Enter SBU Name and SBU Code on every row. Use monthly Excel dates and the existing measure labels. Upload one complete pricing worksheet per SBU. Multiple SBU pricing files can be selected together through a matching destination or automatic SBU detection.</p>`)+panel('Template requirements','Revised SBU-based workbooks are supported.',`<p>Income Statement: SBU Name, SBU Code, Segment, Particulars, followed by monthly Budget / Actual pairs.</p><p>Expense Break-up: SBU Name, SBU Code, General Ledger, Sub-Ledger, Particulars, followed by monthly Budget / Actual pairs.</p><p>Balance Sheet and Cash Flow: SBU identifiers, statement categories/groups and particulars, followed by monthly values.</p><p>Changes in Equity: SBU name, Statement of Changes in Equity title, Share Capital, Retained Earnings, Other Components of Equity and Total columns, with dated opening and closing balances. SEC and CSE worksheet names are supported.</p><p>Net Sales Price: SBU Name, SBU Code, Product Name, Particulars, followed by monthly Excel dates. Measures: Sales [product], Less :VAT, Net Sales Price or NPS, Net Sales Price in KG, Cost per KG. Rates are monthly and have no Budget/Actual split.</p><p>Missing values stay blank. Uploads are saved in this browser and do not automatically synchronise to other devices.</p>`);}
const segmentPrepare=prepareBatch;prepareBatch=function(changes,names){if(uploadSelection.sbu==='auto'&&uploadSelection.segment!=='all'){const allowed=uploadSelection.segment==='financial'?['balance','cashflow','equity']:[uploadSelection.segment];if(changes.some(c=>!allowed.includes(c.kind)))throw Error('A worksheet does not match the selected statement segment.');}if(uploadTarget){const allowed=uploadTarget.segment==='all'?null:uploadTarget.segment==='financial'?['balance','cashflow','equity']:[uploadTarget.segment];for(let i=0;i<changes.length;i++){const c=changes[i];if(allowed&&!allowed.includes(c.kind))throw Error(bookType(c.kind)+' does not match the selected statement segment.');const sameName=keyOf(c.sbuName)===keyOf(uploadTarget.name),sameCode=uploadTarget.code&&keyOf(c.book.sbuCode)===keyOf(uploadTarget.code);if(!sameName&&!sameCode)throw Error('Source SBU '+c.sbuName+' does not match destination '+uploadTarget.name+'. Correct the destination or source identifiers.');if(keyOf(names[i])!==keyOf(uploadTarget.name))throw Error('All worksheets must use the selected destination SBU.');}}const next=segmentPrepare(changes,names);for(let i=0;i<changes.length;i++){const s=next.sbus[makeSbuId(names[i])];if(changes[i].book.sbuCode)s.code=changes[i].book.sbuCode;s.books[changes[i].kind].importedAt=new Date().toISOString();}return next;};
const priorReview=reviewBatch;reviewBatch=function(){if(uploadSelection.sbu==='auto'&&uploadSelection.segment!=='all'){const allowed=uploadSelection.segment==='financial'?['balance','cashflow','equity']:[uploadSelection.segment];if(pendingBatch.some(c=>!allowed.includes(c.kind)))throw Error('A worksheet does not match the selected statement segment.');}if(uploadTarget){const allowed=uploadTarget.segment==='all'?null:uploadTarget.segment==='financial'?['balance','cashflow','equity']:[uploadTarget.segment];for(const c of pendingBatch){if(allowed&&!allowed.includes(c.kind))throw Error(bookType(c.kind)+' does not match selected segment. Choose Multiple segments for mixed files.');if(keyOf(c.sbuName)!==keyOf(uploadTarget.name)&&!(uploadTarget.code&&keyOf(c.book.sbuCode)===keyOf(uploadTarget.code)))throw Error('The file belongs to '+c.sbuName+', not '+uploadTarget.name+'. Select the matching SBU.');}priorReview();pendingBatch.forEach((c,i)=>{$('batch-'+i).value=uploadTarget.name;$('batch-'+i).readOnly=true;});}else priorReview();};
const priorUploadBind=bind;bind=function(){priorUploadBind();if(state.view!=='upload')return;$('uploadSbu').onchange=e=>{uploadSelection.sbu=e.target.value;render();};$('uploadSegment').onchange=e=>{uploadSelection.segment=e.target.value;};if($('newSbuName'))$('newSbuName').oninput=e=>uploadSelection.name=e.target.value;if($('newSbuCode'))$('newSbuCode').oninput=e=>uploadSelection.code=e.target.value;$('chooseSegmentFiles').onclick=()=>{if(uploadSelection.sbu==='auto'){uploadTarget=null;$('files').click();return;}const s=portfolio.sbus[uploadSelection.sbu],name=clean(s?.name||uploadSelection.name),code=clean(s?.code||s?.books.income?.sbuCode||uploadSelection.code);if(!name||(!s&&!code)){$('status').textContent='Enter both SBU name and code before selecting files.';return;}uploadTarget={name,code,segment:uploadSelection.segment};$('files').click();};};

