addAttachedFinancials=async function(saved){let next=await loadAGLSources(saved);if(next.additionalSbusRevision==='acl-ail-2026-10-15')return next;const additions=await(await fetch('additional-sbus.json',{cache:'no-store'})).json();next=structuredClone(next);for(const sbu of Object.values(additions)){const canonical=makeSbuId(sbu.name),existing=Object.entries(next.sbus).find(([id,s])=>keyOf(s.code||s.books.income?.sbuCode||'')===keyOf(sbu.code));const id=existing?.[0]||canonical;next.sbus[id]={...next.sbus[id],name:sbu.name,code:sbu.code,books:{...next.sbus[id]?.books,...sbu.books}};}next.additionalSbusRevision='acl-ail-2026-10-15';await persist(next);return next;};
